// Activity and rollouts are simulated. Fleet values always derive from the same data.
const activity=[];
let livePaused=false,liveTick=0,lastSync=Date.now();
const ops=document.createElement('section');ops.className='operations';ops.setAttribute('aria-label','Live demo fleet activity');
ops.innerHTML=`<div><div class="ops-title"><strong>Fleet pulse</strong><span id="pulse-total">1,248 assets</span></div><div class="fleet-track" id="fleet-track" role="img" aria-label="Fleet status distribution"></div><div class="fleet-legend"><span><i class="dot green"></i>Patched</span><span><i class="dot amber"></i>Reboot</span><span><i class="dot crimson"></i>At risk</span></div></div><div class="event-preview"><div class="event-header"><span class="signal" aria-hidden="true"><i></i><i></i><i></i></span> SIMULATED LIVE ACTIVITY <button class="ops-details" id="activity-details">History</button></div><div class="event-message" id="event-message"></div></div><div class="ops-controls"><time class="ops-clock" id="ops-clock"></time><button class="button pause-live" id="pause-live" aria-pressed="false">Ⅱ Pause</button></div>`;
$('#fleet-panel').before(ops);
function addActivity(message){activity.unshift({message,time:new Date()});activity.splice(20);const e=$('#event-message');e.textContent=message;e.classList.remove('changed');requestAnimationFrame(()=>e.classList.add('changed'));}
function updatePulse(){const total=data.reduce((s,a)=>s+a.assets,0);const statuses=[['compliant','var(--green)'],['reboot','var(--amber)'],['critical','var(--red)'],['deploying','#9db6cb']];$('#fleet-track').innerHTML=statuses.map(([status,color])=>{const count=data.filter(a=>a.status===status).reduce((s,a)=>s+a.assets,0);return `<span style="width:${count/total*100}%;background:${color}" title="${labels[status]}: ${count} assets"></span>`}).join('');$('#fleet-track').setAttribute('aria-label',statuses.map(([status])=>`${labels[status]}: ${data.filter(a=>a.status===status).reduce((s,a)=>s+a.assets,0)} assets`).join(', '));}
const baseRender=render;
render=function(){const focused=document.activeElement;const key=focused?.dataset?.detail!==undefined?['detail',focused.dataset.detail]:focused?.dataset?.select!==undefined?['select',focused.dataset.select]:focused?.dataset?.view?['view',focused.dataset.view]:null;baseRender();updatePulse();if(key){document.querySelector(`[data-${key[0]}="${key[1]}"]`)?.focus({preventScroll:true})}};
const baseNotify=notify;notify=function(message){baseNotify(message);addActivity(message.replace(/^Demo /,''));lastSync=Date.now()};
$('#pause-live').onclick=()=>{livePaused=!livePaused;ops.classList.toggle('paused',livePaused);$('#pause-live').textContent=livePaused?'▶ Resume':'Ⅱ Pause';$('#pause-live').setAttribute('aria-pressed',String(livePaused));addActivity(livePaused?'Live simulation paused. Resume when you’re ready.':'Live simulation resumed. Watching active rollouts.');};
$('#activity-details').onclick=()=>{$('#detail-content').innerHTML='<div class="eyebrow">SIMULATED LIVE ACTIVITY</div><h2>Recent fleet events</h2><p>Updates from this demo session.</p><div class="event-history"></div>';const list=$('.event-history');activity.forEach(item=>{const row=document.createElement('div');row.className='event-entry';const time=document.createElement('time');time.textContent=item.time.toISOString().slice(11,19);const text=document.createElement('span');text.textContent=item.message;row.append(time,text);list.append(row)});$('#detail').showModal()};
$('#scan').addEventListener('click',()=>{document.body.classList.add('scan-active');$('#scan').innerHTML=icon('refresh')+'Scanning fleet…';addActivity('Fleet scan started · Checking all 1,248 assets');setTimeout(()=>document.body.classList.remove('scan-active'),1850)});
data.filter(a=>a.status==='deploying').forEach(a=>a.dynamic=true);
addActivity('Connected to demo fleet · 2 rollouts in progress');updatePulse();
function tickLive(){if(document.hidden||livePaused||view==='scan')return;liveTick++;$('#ops-clock').textContent=new Date().toISOString().slice(11,19)+' UTC';$('#sync-time').textContent=Math.floor((Date.now()-lastSync)/1000)<5?'just now':`${Math.floor((Date.now()-lastSync)/1000)}s ago`;if(liveTick%4)return;const running=data.filter(a=>a.dynamic&&a.status==='deploying');if(!running.length)return;const finished=[];running.forEach(a=>{a.progress=Math.min(100,a.progress+3);if(a.progress===100){a.status='reboot';a.missing=0;a.dynamic=false;finished.push(a)}});lastSync=Date.now();if(finished.length){render();finished.forEach(a=>notify(`${a.name}: patch installed. Reboot required.`));return}running.forEach(a=>{const row=document.querySelector(`[data-detail="${a.id}"]`)?.closest('tr');if(row){const bar=row.querySelector('.row-progress');if(bar){bar.setAttribute('aria-valuenow',a.progress);bar.firstElementChild.style.width=a.progress+'%'}const label=row.querySelector('.status-sub');if(label)label.textContent=a.progress+'% deployed'}const bar=document.querySelector(`.progress[aria-label="${a.name}"]`);if(bar){bar.setAttribute('aria-valuenow',a.progress);bar.firstElementChild.style.width=a.progress+'%';const bottom=bar.parentElement.querySelector('.rollout-bottom');bottom.firstElementChild.textContent=`${Math.floor(a.assets*a.progress/100)} of ${a.assets} assets patched`;bottom.lastElementChild.textContent=a.progress+'% complete'}});const a=running[Math.floor(liveTick/4)%running.length];addActivity(`${a.name} · ${Math.floor(a.assets*a.progress/100)} / ${a.assets} assets patched`);}
tickLive();setInterval(tickLive,1000);

